changes.after:
    tracker = PhaseTracker(unit, deadline)
    tracker.enter('timer-armed')
    message = full_observation(unit, deadline, tracker.enter)
    if time.monotonic() >= deadline:
        raise TimeoutError('Environment packet budget exhausted')
    try:
        if os.write(1, message) != len(message):
            raise OSError('Environment packet write incomplete')
    except BaseException:
        tracker.broken = True
        raise
    tracker.finish()
except BaseException as error:
    # No error text/type/native field is reflected; terminal observation is optional.
    if tracker is not None:
        try:
            tracker.fail(error)
        except BaseException:
            pass

def full_observation(unit, deadline, phase=None):
    mark = phase if phase is not None else lambda _stage: None
    mark('context-read')

# Diagnostic states only. None establishes source/process/environment/admission authority.
PHASE_PREFIX = 'AIHR_OWNED_ENV_OBSERVER_PHASE_V1 '
PHASES = ('timer-armed', 'context-read', 'profile-bound', 'helpers-bound',
    'observer-loaded', 'main-selector', 'declaration-before', 'process-before',
    'environment-read', 'environment-classified', 'process-after', 'custody-after',
    'environment-packet')


def validate_phase_observation(value, subject):
    if (type(value) is not dict or set(value) != {'version', 'kind', 'subject', 'sequence', 'phase', 'result', 'cause'}
            or type(value['version']) is not int or value['version'] != 1
            or value['kind'] != 'OWNED_OBSERVER_PHASE_NOT_ENVIRONMENT_OR_ADMISSION'
            or subject not in ('worker-1', 'worker-2') or value['subject'] != subject
            or type(value['sequence']) is not int or value['phase'] not in PHASES
            or value['result'] not in ('entered', 'failed', 'finished')
            or value['cause'] not in ('none', 'refused', 'budget', 'io', 'other')):
        raise ValueError('Closed observer phase required')
    index = PHASES.index(value['phase'])
    if (value['result'] == 'entered' and (value['sequence'] != index or value['cause'] != 'none')
            or value['result'] == 'failed' and (value['sequence'] != index + 1 or value['cause'] == 'none')
            or value['result'] == 'finished' and (index != len(PHASES) - 1
                or value['sequence'] != len(PHASES) or value['cause'] != 'none')):
        raise ValueError('Observer phase transition refused')
    return value


class PhaseTracker:
    """Private bounded helper telemetry. A copied phase packet proves no native state."""
    def __init__(self, unit, deadline):
        self.subject, self.deadline = 'worker-' + unit[9], deadline
        self.index, self.terminal, self.broken = -1, False, False

    def write(self, result, cause='none'):
        if self.broken or self.terminal or time.monotonic() >= self.deadline:
            raise TimeoutError('Observer phase budget unavailable')
        value = validate_phase_observation({'version': 1,
            'kind': 'OWNED_OBSERVER_PHASE_NOT_ENVIRONMENT_OR_ADMISSION', 'subject': self.subject,
            'sequence': self.index if result == 'entered' else self.index + 1,
            'phase': PHASES[self.index], 'result': result, 'cause': cause}, self.subject)
        message = PHASE_PREFIX.encode() + (json.dumps(value, sort_keys=True, separators=(',', ':')) + '\n').encode()
        if len(message) > 1024:
            raise ValueError('Observer phase bound refused')
        # One bounded framed write. Never retry an uncertain or partial record.
        try:
            if time.monotonic() >= self.deadline:
                raise TimeoutError('Observer phase budget exhausted')
            if os.write(1, message) != len(message):
                raise OSError('Observer phase write incomplete')
        except BaseException:
            self.broken = True
            raise
        if result != 'entered':
            self.terminal = True

    def enter(self, phase):
        if self.terminal or self.broken or phase not in PHASES or PHASES.index(phase) != self.index + 1:
            raise ValueError('Observer phase order refused')
        self.index += 1
        self.write('entered')

    def finish(self):
        if self.index != len(PHASES) - 1:
            raise ValueError('Incomplete observer phases')
        self.write('finished')

    def fail(self, error):
        if self.index < 0 or self.terminal or self.broken or time.monotonic() >= self.deadline:
            return
        cause = 'budget' if isinstance(error, TimeoutError) else 'io' if isinstance(error, OSError) else \
            'refused' if isinstance(error, (ValueError, AssertionError)) else 'other'
        self.write('failed', cause)

require(stages == ['declaration-before', 'process-before', 'environment-read',
        'environment-classified', 'process-after', 'custody-after'], 'Actual native hook sequence differs')
return result, {'kind': 'ACTUAL_SHARED_OBSERVER_HOOKS_NOT_FULL_HELPER_OR_NEXT', 'stages': stages,
    'fullHelperVerified': False, 'nextApplicationVerified': False, 'releaseEligible': False}

def runtime_environment_journal_diagnostic(raw, unit, invocation, python_exe, sources, binding):
    """New phase failure cannot discard an original validated environment observation."""
    observed = runtime_environment_journal_observation(raw, unit, invocation, python_exe, sources, binding)
    try:
        return _runtime_environment_phase_diagnostic(raw, unit, invocation, python_exe, sources, observed)
    except BaseException:
        return {'observations': observed, 'diagnostic': {'kind': 'CLOSED_OBSERVER_PHASE_DIAGNOSTIC_NOT_ENVIRONMENT_OR_ADMISSION',
            'unit': RUNTIME_DIAGNOSTIC_UNITS[unit], 'state': 'receiver-unavailable', 'phases': [],
            'census': None, 'phaseUnavailable': True}}


def _runtime_environment_phase_diagnostic(raw, unit, invocation, python_exe, sources, observed):
    # Original source and outer JSON/duplicate/transport checks have completed.
    P = types.ModuleType('sealed_observer_phase_receiver')
    P.__file__ = '/usr/local/lib/aihr-admission/next_fixture_poststart.py'
    N = types.ModuleType('sealed_observer_prefix_owner')
    N.__file__ = OBSERVER_PATHS['next-profile']
    exec(compile(sources['poststart'], P.__file__, 'exec', dont_inherit=True), P.__dict__)
    exec(compile(sources['next-profile'], N.__file__, 'exec', dont_inherit=True), N.__dict__)
    commands = {prefix + ' -I -B /usr/local/lib/aihr-admission/next_fixture_poststart.py ' + unit
                for prefix in ('/usr/bin/python3', python_exe)}
    controllers = {prefix + ' -I -B /usr/local/lib/aihr-admission/controller.py admit ' + unit
                   for prefix in ('/usr/bin/python3', python_exe)}
    census = {'kind': 'UNTRUSTED_PREFIX_TRANSPORT_COUNTS_NOT_HELPER_OR_ENVIRONMENT_PROOF',
        'records': 0, 'environmentCandidates': 0, 'phaseCandidates': 0, 'trustedHelperCandidates': 0,
        'metadataMatches': dict.fromkeys(('uid', 'executable', 'unit', 'invocation'), 0),
        'commandClasses': dict.fromkeys(('helper', 'controller', 'other-or-missing'), 0)}
    phases, unavailable = [], False
    def unique(pairs):
        value = {}
        for key, item in pairs:
            require(key not in value, 'Duplicate observer phase field')
            value[key] = item
        return value
    for line in raw.splitlines():
        row = json.loads(line);census['records'] += 1
        message = row.get('MESSAGE') if type(row) is dict else None
        if type(message) is not str:
            continue
        phase = message.startswith(P.PHASE_PREFIX)
        environment = message.startswith(N.ENVIRONMENT_OBSERVATION_PREFIX)
        if not (phase or environment):
            continue
        census['phaseCandidates' if phase else 'environmentCandidates'] += 1
        matches = {'uid': row.get('_UID') == '0', 'executable': row.get('_EXE') == python_exe,
            'unit': row.get('_SYSTEMD_UNIT') == unit, 'invocation': row.get('_SYSTEMD_INVOCATION_ID') == invocation}
        for key, matched in matches.items():
            census['metadataMatches'][key] += int(matched)
        command = row.get('_CMDLINE')
        classification = 'helper' if type(command) is str and command in commands else \
            'controller' if type(command) is str and command in controllers else 'other-or-missing'
        census['commandClasses'][classification] += 1
        trusted = all(matches.values()) and classification == 'helper'
        if trusted:
            census['trustedHelperCandidates'] += 1
        if not phase or not trusted:
            continue
        try:
            require(len(message.encode()) <= 1024, 'Observer phase message bound refused')
            value = P.validate_phase_observation(json.loads(message[len(P.PHASE_PREFIX):], object_pairs_hook=unique), RUNTIME_DIAGNOSTIC_UNITS[unit])
            # Full-helper ledger starts at timer-armed. Host hook subsequences do
            # not become full-helper execution evidence through this receiver.
            require(not phases or phases[-1]['result'] == 'entered', 'Observer phase after terminal')
            require(value['sequence'] == len(phases) and len(phases) < 14, 'Observer phase sequence refused')
            if value['result'] != 'entered':
                require(phases and value['phase'] == phases[-1]['phase'], 'Observer terminal phase differs')
            phases.append(value)
        except BaseException:
            unavailable = True
    # Never publish a partial accepted ledger after a malformed/duplicate/foreign
    # transition. Census remains explicitly untrusted; valid original observations survive.
    if unavailable:
        phases = []
    state = 'environment-observed' if observed else 'phase-only' if phases else \
        'untrusted-candidates-only' if census['environmentCandidates'] + census['phaseCandidates'] else 'no-candidates'
    if unavailable:
        state = 'receiver-unavailable'
    return {'observations': observed, 'diagnostic': {'kind': 'CLOSED_OBSERVER_PHASE_DIAGNOSTIC_NOT_ENVIRONMENT_OR_ADMISSION',
        'unit': RUNTIME_DIAGNOSTIC_UNITS[unit], 'state': state, 'phases': phases, 'census': census,
        'phaseUnavailable': unavailable}}
